import { NextResponse } from "next/server";
import { createAdminClient } from "@/lib/supabase/admin";

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Public, read-only order lookup used by the production tracker.
 *
 * Only the fields a customer needs to see are returned — no email, phone or
 * full address. The order id is an unguessable UUID generated by the database.
 */
export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  if (!UUID_PATTERN.test(id)) {
    return NextResponse.json({ error: "Order not found." }, { status: 404 });
  }

  const admin = createAdminClient();
  if (!admin) {
    return NextResponse.json(
      { error: "Order tracking is temporarily unavailable." },
      { status: 503 }
    );
  }

  const { data: order, error } = await admin
    .from("orders")
    .select("id, status, total_amount, currency, created_at, shipping_address, order_items(product_name, quantity, unit_price)")
    .eq("id", id)
    .maybeSingle();

  if (error) {
    console.error("Order lookup failed:", error.message);
    return NextResponse.json({ error: "Order lookup failed." }, { status: 500 });
  }

  if (!order) {
    return NextResponse.json({ error: "Order not found." }, { status: 404 });
  }

  const address = (order.shipping_address ?? {}) as {
    name?: string;
    city?: string;
    state?: string;
    pincode?: string;
  };

  const items = Array.isArray(order.order_items) ? order.order_items : [];

  return NextResponse.json({
    id: order.id,
    status: order.status,
    totalAmount: Number(order.total_amount) || 0,
    currency: order.currency ?? "INR",
    createdAt: order.created_at,
    shipping: {
      name: address.name ?? null,
      city: address.city ?? null,
      state: address.state ?? null,
      pincode: address.pincode ?? null,
    },
    items: items.map((item: { product_name?: string; quantity?: number; unit_price?: number }) => ({
      name: item.product_name ?? "Custom label batch",
      quantity: Number(item.quantity) || 0,
      unitPrice: Number(item.unit_price) || 0,
    })),
  });
}
